css:
.orgchart-sim-container {
    padding: 28px 32px;
    background: #f5f6f8;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', Helvetica, Arial, sans-serif;
    color: #1a1a2e;
    max-width: 960px;
    margin: 0 auto;
}
.orgchart-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 32px 36px;
    border-radius: 4px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.orgchart-sim-header::after {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    width: 200px;
    height: 100%;
    background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.04) 100%);
}
.orgchart-sim-badge {
    display: inline-block;
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.25);
    padding: 4px 14px;
    border-radius: 2px;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    margin-bottom: 14px;
}
.orgchart-sim-header h1 {
    font-size: 1.85rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    letter-spacing: -0.02em;
}
.orgchart-sim-subtitle {
    font-size: 0.88rem;
    opacity: 0.82;
    margin: 0;
    font-weight: 400;
}
.orgchart-sim-period {
    text-align: center;
    font-size: 0.82rem;
    color: #5a6178;
    margin-bottom: 22px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.orgchart-sim-period span {
    margin: 0 3px;
}
.orgchart-sim-kpi-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.orgchart-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e2e4ea;
    border-radius: 4px;
    padding: 20px 16px;
    text-align: center;
    border-top: 3px solid #1a2744;
    transition: box-shadow 0.2s ease;
}
.orgchart-sim-kpi-card:hover {
    box-shadow: 0 4px 16px rgba(26,39,68,0.08);
}
.orgchart-sim-kpi-score { border-top-color: #1a2744; }
.orgchart-sim-kpi-ebitda { border-top-color: #276749; }
.orgchart-sim-kpi-speed { border-top-color: #c05621; }
.orgchart-sim-kpi-consistency { border-top-color: #2b6cb0; }
.orgchart-sim-kpi-label {
    font-size: 0.68rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6b7280;
    margin-bottom: 8px;
}
.orgchart-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.orgchart-sim-kpi-score .orgchart-sim-kpi-value { color: #1a2744; }
.orgchart-sim-kpi-ebitda .orgchart-sim-kpi-value { color: #276749; }
.orgchart-sim-kpi-speed .orgchart-sim-kpi-value { color: #c05621; }
.orgchart-sim-kpi-consistency .orgchart-sim-kpi-value { color: #2b6cb0; }
.orgchart-sim-kpi-sub {
    font-size: 0.68rem;
    color: #6b7280;
    margin-top: 5px;
}
.orgchart-sim-briefing {
    background: #ffffff;
    border: 1px solid #e2e4ea;
    border-left: 4px solid #1a2744;
    border-radius: 0 4px 4px 0;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.orgchart-sim-briefing-header {
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #1a2744;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid #eef0f4;
}
.orgchart-sim-briefing-body {
    font-size: 0.88rem;
    line-height: 1.7;
    color: #374151;
}
.orgchart-sim-briefing-body strong {
    color: #1a2744;
    font-weight: 700;
}
.orgchart-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e4ea;
    border-radius: 4px;
    padding: 28px;
    margin-bottom: 24px;
}
.orgchart-sim-controls-heading {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 2px solid #e2e4ea;
}
.orgchart-sim-field {
    margin-bottom: 18px;
}
.orgchart-sim-field label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #374151;
    margin-bottom: 6px;
}
.orgchart-sim-field input[type="number"],
.orgchart-sim-field select {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 0.88rem;
    color: #1a1a2e;
    background: #f9fafb;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    -webkit-appearance: none;
}
.orgchart-sim-field input[type="number"]:focus,
.orgchart-sim-field select:focus {
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.08);
    outline: none;
    background: #ffffff;
}
.orgchart-sim-field-hint {
    font-size: 0.72rem;
    color: #6b7280;
    margin-top: 4px;
    font-style: italic;
}
.orgchart-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid #eef0f4;
}
.orgchart-sim-submit {
    background: #1a2744;
    border-color: #1a2744;
    padding: 10px 32px;
    font-weight: 600;
    font-size: 0.88rem;
    letter-spacing: 0.02em;
    border-radius: 4px;
    transition: background 0.2s ease, box-shadow 0.2s ease;
}
.orgchart-sim-submit:hover {
    background: #2c3e6b;
    border-color: #2c3e6b;
    box-shadow: 0 4px 12px rgba(26,39,68,0.2);
}
.orgchart-sim-undo {
    font-size: 0.78rem;
    color: #6b7280;
    border-color: #d1d5db;
}
.orgchart-sim-undo:hover {
    color: #374151;
    border-color: #9ca3af;
}
.orgchart-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #e2e4ea;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
    height: 300px;
}
.orgchart-sim-history {
    background: #ffffff;
    border: 1px solid #e2e4ea;
    border-radius: 4px;
    padding: 24px;
    overflow-x: auto;
}
.orgchart-sim-history .table {
    margin: 0;
    font-size: 0.82rem;
}
.orgchart-sim-history .table thead th {
    background: #f5f6f8;
    border-top: none;
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #6b7280;
    padding: 10px 14px;
}
.orgchart-sim-history .table td {
    padding: 10px 14px;
    vertical-align: middle;
    color: #374151;
}
.orgchart-sim-history .table tbody tr:hover {
    background: #f9fafb;
}
@media (max-width: 768px) {
    .orgchart-sim-container {
        padding: 16px;
    }
    .orgchart-sim-kpi-row {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }
    .orgchart-sim-header {
        padding: 24px 20px;
    }
    .orgchart-sim-header h1 {
        font-size: 1.4rem;
    }
    .orgchart-sim-kpi-value {
        font-size: 1.5rem;
    }
    .orgchart-sim-controls {
        padding: 20px;
    }
    .orgchart-sim-briefing {
        padding: 20px;
    }
}

/* EQIL 2026-10-28: contrast (AA), focus, reduced motion, board-review debrief */
.orgchart-sim-kpi-label, .orgchart-sim-kpi-sub, .orgchart-sim-field-hint, .orgchart-sim-undo,
.orgchart-sim-history .table thead th { color: #666d7a; }
.orgchart-sim-kpi-speed .orgchart-sim-kpi-value { color: #b8521f; }
.orgchart-sim-container button:focus-visible, .orgchart-sim-container input:focus-visible,
.orgchart-sim-container select:focus-visible { outline: 3px solid #1a2744; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .orgchart-sim-container * { transition: none !important; animation: none !important; } }
.orgchart-sim-cm { text-align: left; max-width: 720px; margin: 0 auto; color: #1f2937; }
.orgchart-sim-cm-h { font-size: 1.25rem; margin: 0 0 8px; color: #1a2744; }
.orgchart-sim-cm-h4 { font-size: 1rem; margin: 16px 0 6px; color: #1a2744; }
.orgchart-sim-cm-score { font-size: 1.1rem; margin: 0 0 4px; }
.orgchart-sim-cm-sub { margin: 0 0 12px; color: #4b5563; }
.orgchart-sim-cm-kpis { list-style: none; padding: 0; margin: 0 0 12px; display: flex; flex-wrap: wrap; gap: 8px; }
.orgchart-sim-cm-kpis li { flex: 1 1 160px; background: #f5f6f8; border-radius: 8px; padding: 8px 12px; display: flex; flex-direction: column; }
.orgchart-sim-cm-kpis span, .orgchart-sim-cm-kpis small { color: #4b5563; }
.orgchart-sim-cm-kpis b { font-size: 1.15rem; color: #1a2744; }
.orgchart-sim-cm-turn { background: #fff7ed; border-left: 4px solid #b8521f; padding: 8px 12px; margin: 0 0 8px; }
.orgchart-sim-cm-list { padding-left: 20px; margin: 0; }
.orgchart-sim-cm-list li { margin-bottom: 6px; line-height: 1.45; }

