                if (!Number.isFinite(decisions.delegationThreshold) || decisions.delegationThreshold < 0 || decisions.delegationThreshold > 10) return warn('raci_warning');
            } else if (period === 4) {
                decisions.timelineMonths = num('timelineInput');
                decisions.reorgBudget = num('budgetInput');
                decisions.changeApproach = sel('changeApproachSelect');
                if (!decisions.changeApproach) return warn('choose_warning');
                if (!Number.isFinite(decisions.timelineMonths) || decisions.timelineMonths < 1 || decisions.timelineMonths > 18) return warn('impl_warning');
                if (!Number.isFinite(decisions.reorgBudget) || decisions.reorgBudget < 50000 || decisions.reorgBudget > 2000000) return warn('budget_warning');
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        // Pure model. c holds every choice made so far; stage is the round just scored (1 to 4).
        // Returns the KPIs the board sees after that stage and the points of each part.
        // Stages 2 and 3 show the KPIs the design would deliver once fully implemented; stage 4 shows
        // what the rollout actually realises (adoption factor), so a weak rollout lands late.
        _project(c, stage) {
            var ALIGN = { authority_confusion: 1, lack_specialization: 0.85, excessive_span: 0.8,
                          financial_fragmentation: 0.65, slow_decisions: 0.55 };
            var A = ALIGN[c.primaryProblem] != null ? ALIGN[c.primaryProblem] : 0.6;
            var dm = 0, dsp = 0, dc = 0, pts = { r1: 0, r2: 0, r3: 0, r4: 0, outcome: 0 };
            var div = c.structureType === 'divisional';

            // Stage 1: diagnosis. True average span = (50 + 150 + 120) / 3, about 107.
            var est = Number(c.estimatedSpan);
            var off = Math.abs((Number.isFinite(est) ? est : 0) - 107);
            pts.r1 = (off <= 20 ? 8 : off <= 40 ? 5 : off <= 60 ? 2 : 0) +
                ({ authority_confusion: 12, slow_decisions: 12, lack_specialization: 9,
                   excessive_span: 9, financial_fragmentation: 7 }[c.primaryProblem] || 0);

            if (stage >= 2) {
                // Structure: [consistency gain, days saved, margin points]
                var S = { functional: [30, 6, 0.50], hybrid: [26, 5, 0.35], matrix: [16, 1, 0.20], divisional: [6, 4, -0.15] }[c.structureType] || [0, 0, 0];
                var need = div ? 2 : 3;
                var n = Number(c.numVPRoles) || 0, miss = Math.max(0, need - n), extra = Math.max(0, n - need);
                dc += S[0] - 6 * miss;
                dsp += S[1] - 3 * miss - Math.max(0, extra - 1);
                dm += S[2] - 0.07 * extra;
                // Layers CEO to front line: span per manager = 500^(1/(L-1)); L = 4 gives about 8
                var L = Number(c.managementLayers) || 4;
                if (L > 4) { dsp -= 2.5 * (L - 4); dm -= 0.2 * (L - 4); }
                if (L < 4) { dsp -= 1.5 * (4 - L); dc -= 8 * (4 - L); }
                pts.r2 = ({ functional: 7, hybrid: 6, matrix: 3, divisional: 3 }[c.structureType] || 0) +
                    (extra <= 1 && miss === 0 ? 4 : (miss === 1 || extra === 2) ? 2 : 0) +
                    (L === 4 ? 4 : (L === 3 || L === 5) ? 2 : 0);
            }
            if (stage >= 3) {
                var D = { vp_sales: [26, 7, 0.25], cfo: [22, 4, 0.20], ceo: [24, -3, 0.05], regional_manager: [2, 7, -0.10] }[c.discountAuthority] || [0, 0, 0];
                // a national VP or the CFO cannot hold one price line when each region is its own division
                dc += D[0] * (div && (c.discountAuthority === 'vp_sales' || c.discountAuthority === 'cfo') ? 0.6 : 1);
                dsp += D[1]; dm += D[2];
                var t = Number(c.delegationThreshold);
                if (!Number.isFinite(t)) t = 0;
                if (t === 0) dsp -= 4; else dsp += Math.min(t, 3);
                if (t > 3) { dm -= 0.09 * (t - 3); dc -= 2.5 * (t - 3); }
                var I = { vp_logistics: [5, 0, 0.35], vp_operations: [4, 0, 0.25], cfo: [3, -1, 0.12], regional_manager: [0, 0, -0.05] }[c.inventoryAuthority] || [0, 0, 0];
                dc += I[0]; dsp += I[1];
                dm += I[2] * (div && (c.inventoryAuthority === 'vp_logistics' || c.inventoryAuthority === 'vp_operations') ? 0.5 : 1);
                pts.r3 = ({ vp_sales: 6, ceo: 6, cfo: 5, regional_manager: 1 }[c.discountAuthority] || 0) +
                    ((t >= 2 && t <= 3) ? 5 : (t === 1 || t === 4) ? 3 : (t === 0 || t === 5) ? 1 : 0) +
                    ({ vp_logistics: 4, vp_operations: 3, cfo: 2, regional_manager: 0 }[c.inventoryAuthority] || 0);
            }
            // A redesign built on a symptom is adopted as a speed fix: regional pricing survives in practice
            dc *= A; dsp *= A;

            var alpha = 1, disruption = 0, slowLoss = 0, overspend = 0;
            if (stage >= 4) {
                var m = Number(c.timelineMonths) || 6, B = Number(c.reorgBudget) || 0, ap = c.changeApproach;
                alpha = { phased_pilot: 1, gradual: 0.9, big_bang: 0.8 }[ap] || 0.8;
                if (m < 4) alpha -= 0.08 * (4 - m);
                if (ap === 'phased_pilot' && m < 4) alpha -= 0.1;
                if (m > 9) alpha -= 0.03 * (m - 9);
                if (B < 400000) alpha -= 0.3 * (1 - B / 400000);
                alpha = Math.max(0.3, Math.min(1, alpha));
                if (ap === 'big_bang') disruption = 0.25 + 0.1 * Math.max(0, 4 - m);
                if (m > 9) slowLoss = 0.05 * (m - 9);
                overspend = Math.max(0, B - 600000) / 1800000;
                pts.r4 = ({ phased_pilot: 4, gradual: 3, big_bang: 3 }[ap] || 0) +
                    ((m >= 5 && m <= 8) ? 3 : (m === 4 || m === 9 || m === 10) ? 2 : (m === 3 || m === 11 || m === 12) ? 1 : 0) +
                    ((B >= 350000 && B <= 650000) ? 3 : (B >= 200000 && B <= 900000) ? 2 : 0);
            }
            var margin = Math.round((4.4 + dm * alpha - disruption - slowLoss - overspend) * 100) / 100;
            var speed = Math.max(3, Math.min(30, Math.round(21 - dsp * alpha)));
            var consistency = Math.max(0, Math.min(98, Math.round(30 + dc * alpha)));
            if (stage >= 4) {
                var cl = function(x) { return Math.max(0, Math.min(1, x)); };
                pts.outcome = Math.round(14 * cl((margin - 4.4) / 1.1) + 13 * cl((21 - speed) / 16) + 13 * cl((consistency - 30) / 60));
            }
            var total = Math.round((pts.r1 + pts.r2 + pts.r3 + pts.r4 + pts.outcome) * 10) / 10;
            return { margin: margin, speed: speed, consistency: consistency, alpha: alpha, align: A,
                     pts: pts, total: Math.max(0, Math.min(100, total)) };
        }

        _computeRound(state) {
            var d = state.decisions || {};
            var ds = state.domainState;
            var period = state.currentPeriod;
            var c = Object.assign({}, ds.choices || {});
            var KEYS = ['estimatedSpan', 'primaryProblem', 'structureType', 'numVPRoles', 'managementLayers',
                        'discountAuthority', 'delegationThreshold', 'inventoryAuthority', 'timelineMonths', 'reorgBudget', 'changeApproach'];
            KEYS.forEach(function(k) { if (d[k] !== undefined && d[k] !== null && d[k] !== '') c[k] = d[k]; });
            ds.choices = c;

            var before = ds.totalScore || 0;
            var p = this._project(c, period);
            var roundScore = Math.round((p.total - before) * 10) / 10;
            var roundName = window.mySimulation.t('r' + period + '_short');

            ds.ebitdaMargin = Math.round(p.margin * 10) / 10;
            ds.decisionSpeed = p.speed;
            ds.consistency = p.consistency;
            ds.totalScore = p.total;
            ds.stagePoints = p.pts;
            ds.scoreHistory.push(roundScore);
            ds.marginHistory.push(ds.ebitdaMargin);
            ds.speedHistory.push(ds.decisionSpeed);
            ds.consistencyHistory.push(ds.consistency);

            // Show the briefing and panel of the next round from the local period (the framework
            // increments currentPeriod only after this method returns)
            this._updateBriefing({ currentPeriod: period + 1 });

            var overallScore = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: overallScore, tier: this._tier(overallScore) });

            return {
                period: state.currentPeriod,
                roundName: roundName,
                roundScore: roundScore,
                ebitdaMargin: ds.ebitdaMargin,
                decisionSpeed: ds.decisionSpeed,
                consistency: ds.consistency,
                totalScore: ds.totalScore,
                overallScore: overallScore,
                score: overallScore
            };
        }

        // Bands derived from the sweep (EQIL 2026-10-28): expert play about 100, random play median about 50
        _tier(score) {
            return score >= 90 ? 'excellent' : score >= 75 ? 'good' : score >= 55 ? 'developing' : 'needs';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin',
                (v) => this._num(v, 1) + '%');
            uiManager.bind('speedDisplay', 'domainState.decisionSpeed',
                (v) => v + ' ' + window.mySimulation.t('days_unit'));
            uiManager.bind('consistencyDisplay', 'domainState.consistency',
                (v) => v + '%');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: window.mySimulation.t('chart_ds_label'),
                            data: [],
                            backgroundColor: ['#1a2744', '#2c5282', '#276749', '#c05621'],
                            borderColor: ['#1a2744', '#2c5282', '#276749', '#c05621'],
                            borderWidth: 1,
                            borderRadius: 3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: window.mySimulation.t('chart_title'), font: { size: 14, weight: '600' } },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 50, ticks: { stepSize: 10 } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = [];
            var keys = ['r1_short', 'r2_short', 'r3_short', 'r4_short'];
            for (var i = 0; i < state.domainState.scoreHistory.length; i++) {
                try {
                    labels.push(window.mySimulation.t(keys[i]));
                } catch(e) {
                    labels.push('R' + (i + 1));
                }
            }
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = document.documentElement && document.documentElement.lang;
            return h ? String(h).slice(0, 2) : 'en';
        }

        _num(v, dec) {
            var s = Number(v).toFixed(dec);
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        // Insights, turning point and sub-scores, built only from the choices this run made
        _debrief(c, p) {
            var self = this;
            var t = function(k, q) { return window.mySimulation.t(k, q); };
            var out = [];
            var m = this._num(p.margin, 1), s = p.speed, cons = p.consistency, a = Math.round(p.alpha * 100);
            if (c.primaryProblem === 'slow_decisions') out.push(t('dx_symptom', { c: cons }));
            else if (c.primaryProblem && c.primaryProblem !== 'authority_confusion') out.push(t('dx_partial', { c: cons }));
            var e = Number(c.estimatedSpan);
            if (Number.isFinite(e) && Math.abs(e - 107) > 40) out.push(t('dx_span_off', { e: e }));
            if (c.structureType === 'divisional') out.push(t('st_divisional', { m: m }));
            if (c.structureType === 'matrix') out.push(t('st_matrix', { s: s }));
            var need = c.structureType === 'divisional' ? 2 : 3, n = Number(c.numVPRoles);
            if (n < need) out.push(t('vp_short', { n: n }));
            if (n > need + 1) out.push(t('vp_many', { n: n }));
            var L = Number(c.managementLayers);
            if (L > 4) out.push(t('layers_many', { L: L, x: this._num(Math.pow(500, 1 / (L - 1)), 1), m: m }));
            if (L < 4) out.push(t('layers_few', { L: L, x: Math.round(Math.pow(500, 1 / (L - 1))) }));
            if (c.discountAuthority === 'ceo') out.push(t('disc_ceo', { s: s }));
            if (c.discountAuthority === 'regional_manager') out.push(t('disc_regional', { c: cons }));
            if (c.discountAuthority === 'cfo') out.push(t('disc_cfo', { s: s }));
            var th = Number(c.delegationThreshold);
            if (th > 3) out.push(t('deleg_high', { t: th }));
            if (th === 0) out.push(t('deleg_zero'));
            if (c.inventoryAuthority === 'regional_manager') out.push(t('inv_regional'));
            if (c.inventoryAuthority === 'cfo') out.push(t('inv_cfo'));
            var mo = Number(c.timelineMonths), B = Number(c.reorgBudget);
            if (c.changeApproach === 'big_bang') out.push(t('impl_bigbang', { m: mo, a: a }));
            else if (mo < 4) out.push(t('impl_rushed', { m: mo, a: a }));
            if (mo > 9) out.push(t('impl_slow', { m: mo }));
            if (B < 400000) out.push(t('budget_low', { b: B.toLocaleString('en-US'), a: a }));
            if (B > 650000) out.push(t('budget_high', { b: B.toLocaleString('en-US') }));

            // Turning point: the single choice whose replacement by the strongest alternative gains most
            var BEST = { estimatedSpan: 107, primaryProblem: 'authority_confusion', structureType: 'functional', numVPRoles: 3,
                         managementLayers: 4, discountAuthority: 'vp_sales', delegationThreshold: 3, inventoryAuthority: 'vp_logistics',
                         timelineMonths: 6, reorgBudget: 450000, changeApproach: 'phased_pilot' };
            var LBL = { estimatedSpan: 'span_label', primaryProblem: 'problem_label', structureType: 'structure_label', numVPRoles: 'vp_label',
                        managementLayers: 'layers_label', discountAuthority: 'discount_auth_label', delegationThreshold: 'delegation_label',
                        inventoryAuthority: 'inventory_auth_label', timelineMonths: 'timeline_label', reorgBudget: 'budget_label', changeApproach: 'change_label' };
            var turnKey = null, gain = 0;
            Object.keys(BEST).forEach(function(k) {
                var cf = Object.assign({}, c); cf[k] = BEST[k];
                var g = self._project(cf, 4).total - p.total;
                if (g > gain + 0.05) { gain = g; turnKey = k; }
            });
            var turning = turnKey && gain >= 2 ? t('turning_point', { d: t(LBL[turnKey]), g: Math.round(gain) }) : t('turning_none');
            var design = Math.round((p.pts.r1 + p.pts.r2 + p.pts.r3 + p.pts.r4) * 10) / 10;
            return { insights: out, turning: turning, turningKey: turnKey, design: design, outcome: p.pts.outcome };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var lastEntry = history[history.length - 1];
            var res = (lastEntry && lastEntry.results) || {};
            var totalScore = typeof res.totalScore === 'number' ? res.totalScore :
                history.reduce(function(s, r) { return s + (r.results ? r.results.roundScore : 0); }, 0);
            var score = Math.max(0, Math.min(100, Math.round(totalScore)));
            var finalMargin = typeof res.ebitdaMargin === 'number' ? res.ebitdaMargin : 4.4;
            var finalSpeed = typeof res.decisionSpeed === 'number' ? res.decisionSpeed : 21;
            var finalConsistency = typeof res.consistency === 'number' ? res.consistency : 30;
            var t = function(k, p) { return window.mySimulation.t(k, p); };
            var tier = this._tier(score);
            var TL = { excellent: 'perf_excellent', good: 'perf_good', developing: 'perf_developing', needs: 'perf_needs' };
            var TI = { excellent: 'insight_excellent', good: 'insight_good', developing: 'insight_developing', needs: 'insight_needs' };
            var insights = [t(TI[tier])];
            var db = null;
            try {
                var ds = window.mySimulation.state.domainState || {};
                if (ds.choices && history.length >= 4) db = this._debrief(ds.choices, this._project(ds.choices, 4));
            } catch (e) { db = null; }
            if (db) insights = insights.concat(db.insights);
            if (finalMargin >= 5.5) insights.push(t('insight_margin', { v: this._num(finalMargin, 1) }));
            if (finalSpeed <= 5) insights.push(t('insight_speed', { v: finalSpeed }));
            if (finalConsistency >= 90) insights.push(t('insight_consistency', { v: finalConsistency }));
            return {
                totalPeriods: history.length,
                totalScore: score,
                overallScore: score,
                score: score,
                composite: score,
                finalMargin: finalMargin,
                finalSpeed: finalSpeed,
                finalConsistency: finalConsistency,
                performance: tier,
                performanceKey: TL[tier],
                performanceLabel: t(TL[tier]),
                turningPoint: db ? db.turning : '',
                designScore: db ? db.design : null,
                outcomeScore: db ? db.outcome : null,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || typeof summary.overallScore !== 'number') return '';
            var t = function(k, q) { return window.mySimulation.t(k, q); };
            var h = '<div class="orgchart-sim-cm" role="region" aria-label="' + t('cm_heading') + '">';
            h += '<h3 class="orgchart-sim-cm-h">' + t('cm_heading') + '</h3>';
            h += '<p class="orgchart-sim-cm-score"><strong>' + summary.overallScore + '/100</strong> &middot; ' + summary.performanceLabel + '</p>';
            if (summary.designScore != null) {
                h += '<p class="orgchart-sim-cm-sub">' + t('cm_design', { v: this._num(summary.designScore, 0) }) + ' &middot; ' +
                     t('cm_outcome', { v: summary.outcomeScore }) + '</p>';
            }
            h += '<ul class="orgchart-sim-cm-kpis">' +
                 '<li><span>' + t('ebitda_label') + '</span><b>' + this._num(summary.finalMargin, 1) + '%</b><small>' + t('ebitda_target') + '</small></li>' +
                 '<li><span>' + t('speed_label') + '</span><b>' + summary.finalSpeed + ' ' + t('days_unit') + '</b><small>' + t('speed_target') + '</small></li>' +
                 '<li><span>' + t('consistency_label') + '</span><b>' + summary.finalConsistency + '%</b><small>' + t('consistency_target') + '</small></li></ul>';
            if (summary.turningPoint) h += '<p class="orgchart-sim-cm-turn"><strong>' + t('cm_turning') + '</strong> ' + summary.turningPoint + '</p>';
            var ins = summary.insights || [];
            h += '<h4 class="orgchart-sim-cm-h4">' + t('cm_insights') + '</h4><ul class="orgchart-sim-cm-list">';
            for (var i = 0; i < ins.length; i++) h += '<li>' + ins[i] + '</li>';
            h += '</ul><h4 class="orgchart-sim-cm-h4">' + t('cm_questions') + '</h4><ol class="orgchart-sim-cm-list">' +
                 '<li>' + t('q1') + '</li><li>' + t('q2') + '</li><li>' + t('q3') + '</li></ol></div>';
            return h;
        }

        getHint(state, results) {
            // relative to the most the round can give: 20, 15, 15, then 50 with the board review
            var MAX = { 1: 20, 2: 15, 3: 15, 4: 50 };
            var r = results && results.period ? results.period : (state && state.currentPeriod) || 1;
            var share = results && MAX[r] ? results.roundScore / MAX[r] : 0;
            if (share >= 0.85) return window.mySimulation.t('hint_high');
            if (share >= 0.6) return window.mySimulation.t('hint_medium');
            return window.mySimulation.t('hint_low');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.ebitdaMargin', label: 'EBITDA %', i18nKey: 'col_ebitda', formatter: (v) => this._num(v, 1) + '%' },
                { key: 'results.decisionSpeed', label: 'Speed (days)', i18nKey: 'col_speed' },
                { key: 'results.consistency', label: 'Consistency', i18nKey: 'col_consistency', formatter: (v) => v + '%' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:               `El Organigrama`,
